  "track.title":        "Bilan — backtest honnête",
  "track.intro":        "Nous avons rejoué chaque combat de la base dans l'ordre chronologique. Pour chacun, MM.AI prédit le vainqueur en n'utilisant <strong>que les données disponibles avant ce combat</strong>, puis apprend le résultat réel — exactement comme le ferait un pronostiqueur en direct. Aucun coup d'œil vers le futur, aucun ajustement sur les réponses. Voici le résultat.",
