  "divisions.hero_sub": "De l'Atomweight au Heavyweight — chaque catégorie, son champion, et les combattants qui la définissent.",
  "analytics.finish_div_title": "Taux de finish par division",
  "analytics.finish_div_sub": "KO/TKO · Soumission · Décision — plus la division est lourde, plus les finitions sont explosives",
