  "track.eyebrow": "Funciona mesmo?",
  "track.title": "Histórico — backtest honesto",
  "track.intro": "Reproduzimos cada luta do nosso banco de dados em ordem cronológica. Para cada uma, o MM.AI prevê o vencedor usando <strong>apenas os dados disponíveis antes dessa luta</strong>, depois aprende o resultado real — sem espiar o futuro.",
