  "methodo.c1_li3": "احتياطي تصنيف الخصم لـ<strong>32% من النزالات</strong> ذات الخصوم المجهولين",
  "methodo.c2_title": "تقييم سكاوتر — درجة ML مركّبة",
  "methodo.c2_intro": "درجة واحدة من <strong>0-100</strong> تجمع أربع مجموعات خصائص مستقلّة، كلٌّ منها يلتقط بُعداً مختلفاً من جودة المقاتل.",
  "methodo.c2_li1": "<strong>مكوّن إيلو</strong> — base_elo مُطبَّع إلى 0-100 لكل فئة",
  "methodo.c2_li2": "<strong>مكوّن المسيرة</strong> — % الفوز، % الحسم، فترات حمل اللقب، الدفاعات عن اللقب، السلسلة",
  "methodo.c2_li3": "<strong>المكوّن الخارجي</strong> — مقاييس تقييم عامة مُجمَّعة و% الجودة",
  "methodo.c2_li4": "<strong>مكوّن المهارات</strong> — دقّة اللكم، المصارعة، الدفاع ضد الإسقاط (UFC Stats)",
  "methodo.c2_callout": "تُطبَّع المكوّنات الأربعة جميعها وتُقاس بطريقة min-max قبل الترجيح، ما يضمن ألا يهيمن مصدر واحد بسبب فروق المقياس.",
  "methodo.c3_title": "هندسة الخصائص",
  "methodo.c3_intro": "يُمثَّل كل مقاتل بـ<strong>متّجه خصائص بأكثر من 30 بُعداً</strong> مُستخرَج من سجل نزالاته الكامل وملفّه متعدّد المصادر.",
  "methodo.c3_body": "تُعاد حوسبة الخصائص في كل دورة جمع. يطبّق <strong>recent_form_score</strong> أوزاناً متزايدة أُسّياً على آخر 5 نزالات، ما يجعل النموذج متجاوباً مع الزخم دون إفراط في الملاءمة على نتيجة واحدة.",
  "methodo.c4_title": "مصادر البيانات — دمج متعدّد المصادر",
  "methodo.c4_intro": "تُتقاطع أربعة مصادر مستقلّة لكل مقاتل لإزالة تحيّز المنصّة الواحدة وتعظيم التغطية.",
  "methodo.c4_s1_desc": "نقاط تقييم المسيرة، % جودة الأداء، سجل البطولات الكبرى — مرجعي عبر كل المنظمات منذ 1993",
  "methodo.c4_s2_desc": "تصنيفات الفئات، قائمة الرطل مقابل الرطل، حالة البطولة، سجل UFC فقط، الجنسية، الوضعية",
  "methodo.c4_s3_desc": "اللكم والمصارعة وزمن السيطرة والدفاع ضد الإسقاط لكل نزال — تفصيل دقيق لكل جولة",
  "methodo.c4_s4_desc": "سجل النزالات الكامل بالتواريخ والطرق وسجلّات الخصوم وقت النزال — يُستخدَم للأداء وإعادة تشغيل إيلو الزمنية",
  "methodo.c4_note": "تُطبّع المطابقة المانعة للتكرار الأسماء (التشكيل، الفواصل العليا) وتتقاطع تاريخ الميلاد لدمج الملفّات عبر المصادر دون إنشاء مقاتلين وهميين.",
  "methodo.c5_title": "محرّك توقّع ML — مقارنة مقاتلَين",
  "methodo.c5_intro": "بإعطاء المقاتلَين A وB، يحسب MM.AI <strong>إيلو ديناميكياً</strong> لكلٍّ منهما بتطبيق أربعة مُعدِّلات آنية على تقييمه الأساسي، ثم يُدخل الفارق في <strong>انحدار لوجستي</strong> لإخراج احتمال فوز.",
  "methodo.c5_step1_lbl": "الخطوة 1 — إيلو ديناميكي (مُعدِّلات آنية)",
  "methodo.c5_step2_lbl": "الخطوة 2 — توقّع لوجستي",
  "methodo.c5_body": "تُشتقّ <strong>طريقة الفوز</strong> المتوقَّعة (KO/TKO، إخضاع، قرار) من توزيع الحسم التاريخي للفائز مرجَّحاً بالإحصاءات الدفاعية لخصمه.",
  "methodo.c5_train_lbl": "مجموعة التدريب",
  "methodo.c5_train_val": "كل النزالات قبل 2023",
